from typing import Dict, List, Set, Tuple

def build_graph(n: int, chords: List[Tuple[int, int]]) -> Dict[int, Set[int]]:
    adj: Dict[int, Set[int]] = {v: set() for v in range(n)}
    for v in range(n):
        adj[v].add((v + 1) % n); adj[(v + 1) % n].add(v)
    for a, b in chords:
        adj[a % n].add(b % n); adj[b % n].add(a % n)
    return adj

def forward_span(n: int, a: int, b: int) -> int:
    return (b - a) % n

def arc_cycle(n: int, a: int, k: int) -> List[int]:
    return [(a + j) % n for j in range(k + 1)]

def chord_arc_cycle(n: int, a: int, b: int) -> List[int]:
    return arc_cycle(n, a, forward_span(n, a, b))

def is_valid_cycle(adj: Dict[int, Set[int]], cycle: List[int]) -> bool:
    if len(cycle) < 3 or len(set(cycle)) != len(cycle):
        return False
    m = len(cycle)
    return all(cycle[(i + 1) % m] in adj[cycle[i]] for i in range(m))

if __name__ == "__main__":
    n, a, b = 12, 2, 9
    adj = build_graph(n, [(a, b)])
    cyc = chord_arc_cycle(n, a, b)
    print("arc cycle:", cyc, "length", len(cyc))
    print("valid?", is_valid_cycle(adj, cyc), "3<=len<n?", 3 <= len(cyc) < n)

from typing import List, Tuple

def forward_span(n: int, a: int, b: int) -> int:
    return (b - a) % n

def is_frame_adjacent(n: int, a: int, b: int) -> bool:
    return b == (a + 1) % n or a == (b + 1) % n

def arc_lengths(n: int, a: int, b: int) -> Tuple[int, int]:
    return forward_span(n, a, b) + 1, forward_span(n, b, a) + 1

if __name__ == "__main__":
    n = 15
    ok = True
    for a in range(n):
        for b in range(n):
            if a == b or is_frame_adjacent(n, a, b):
                continue
            lf, lb = arc_lengths(n, a, b)
            assert lf + lb == n + 2
            assert max(lf, lb) >= n // 2 + 1
    print("Identity L_fwd + L_bwd = n + 2 verified for all chords, n =", n)
