from typing import Dict, List, Set, Tuple

def build_graph(n: int, chords: List[Tuple[int, int]]) -> Dict[int, Set[int]]:
    adj: Dict[int, Set[int]] = {v: set() for v in range(n)}
    for v in range(n):
        adj[v].add((v + 1) % n); adj[(v + 1) % n].add(v)
    for a, b in chords:
        adj[a % n].add(b % n); adj[b % n].add(a % n)
    return adj

def frame_neighbors(n: int, v: int) -> Tuple[int, int]:
    return ((v + 1) % n, (v - 1) % n)

def chord_arc_cycle(n: int, a: int, b: int) -> List[int]:
    k = (b - a) % n
    return [(a + j) % n for j in range(k + 1)]

def find_chord_at(n: int, adj: Dict[int, Set[int]], v: int):
    fn = frame_neighbors(n, v)
    for w in adj[v]:
        if w not in fn and w != v:
            return (v, w)
    return None

if __name__ == "__main__":
    n = 9
    adj = build_graph(n, [(v, (v + 4) % n) for v in range(n)])
    for v in range(n):
        a, b = find_chord_at(n, adj, v)
        cyc = chord_arc_cycle(n, a, b)
        print(f"vertex {v}: cycle len {len(cyc)}, contains v? {v in cyc}")

